  "free_start": [
    {
      "provider": "gemini",
      "model": "gemini-4-hydrogen",
      "line": {
        "ko": "구글 계정만 있으면 무료예요. 무료로 보낸 대화는 Google 이 서비스 개선에 쓸 수 있어요.",
        "en": "Free with just a Google account. Chats sent for free may be used to improve Google's products."
      }
    },
    {
      "provider": "openrouter",
      "model": "nvidia/nemotron-3-ultra-550b-a55b:free",
      "line": {
        "ko": "로그인만 하면 무료 모델을 하루 50번까지 써요. 무료 모델은 그 회사가 대화를 학습에 쓸 수 있어요.",
        "en": "Sign in and use free models up to 50 times a day. Free models' makers may train on your chats."
      }
    }
  ],
  "providers": [
    {
      "id": "chatgpt",
      "section": "subscription",
      "status": "ready",
      "name": {
        "ko": "ChatGPT 구독",
        "en": "ChatGPT plan"
      },
      "tagline": {
        "ko": "ChatGPT 요금제(Plus·Pro 등)로 바로 써요 — 키가 필요 없어요",
        "en": "Use your ChatGPT plan — no key needed"
      },
      "connection": "chatgpt_oauth",
      "base_url": "https://api.openai.com/v1",
      "auth": {
        "type": "oauth_pkce_dynamic",
        "issuer": "https://auth.openai.com",
        "callback": "loopback"
      },
      "manage_url": "https://chatgpt.com/settings/usage",
      "models_api": {
        "path": "/models",
        "shape": "models[].{slug,display_name,visibility}",
        "filter": "visibility == list"
      },
      "default_model_hint": "gpt-6.1-sol",
      "models": [],
      "free": {
        "kind": "subscription",
        "summary": {
          "ko": "ChatGPT 요금제에 포함된 사용량을 써요. 구름이에 따로 내는 돈은 없어요.",
          "en": "Uses the usage included in your ChatGPT plan. Gurumi charges nothing extra."
        },
        "card_required": false
      },
      "training": {
        "ko": "ChatGPT 계정 설정을 따라요.",
        "en": "Follows your ChatGPT account settings."
      },
      "ui": {
        "first_use_notice": {
          "ko": "이제 ChatGPT 요금제를 쓰고 있어요. 사용량은 ChatGPT 설정에서 볼 수 있어요.",
          "en": "You're using your ChatGPT plan. Manage usage in ChatGPT settings."
        },
        "badge": {
          "ko": "ChatGPT 요금제 사용 중",
          "en": "Using ChatGPT plan"
        },
        "limit_primary": {
          "ko": "사용량 관리",
          "en": "Manage usage"
        }
      },
      "quirks": [
        {
          "ko": "공식 문서상 이 경로는 '오픈소스·로컬 실행 앱' 대상이에요. 유료·원격 앱은 OpenAI 관심 신청 양식이 필요해요 — 구름이 배포 형태를 이 조건에 맞춰 확인해야 해요.",
          "en": "Docs scope this flow to open-source and locally hosted apps; paid or remotely hosted apps must use OpenAI's interest form."
        },
        {
          "ko": "Responses 만(store:false·stream:true), max_output_tokens·temperature 등 일부 칸 미지원, 이미지 생성·파일 검색·코드 인터프리터 미지원.",
          "en": "Responses only (store:false, stream:true); some fields and hosted tools are unsupported."
        },
        {
          "ko": "어떤 ChatGPT 요금제(무료·Go 포함 여부)가 되는지는 공식 문서에서 확인 못 함 — 모델 목록 API 결과로 판단.",
          "en": "Which ChatGPT plans qualify (Free/Go?) is not stated in the docs read — rely on the model-list response."
        }
      ],
      "korea": "yes",
      "sources": [
        "https://developers.openai.com/siwc/token-sharing-open-source",
        "https://developers.openai.com/siwc/token-sharing-open-source/models-and-inference",
        "https://developers.openai.com/siwc/token-sharing-open-source/preview-limitations",
        "https://developers.openai.com/siwc/ui-ux-guidelines"
      ],
      "order": 0,
      "request": null,
      "data_policy": {
        "training": "yes",
        "summary": {
          "ko": "ChatGPT 개인 요금제는 기본으로 대화가 학습에 쓰여요. ChatGPT 설정에서 끌 수 있어요.",
          "en": "Personal ChatGPT plans train on chats by default. You can turn it off in ChatGPT settings."
        },
        "opt_out_url": "https://privacy.openai.com",
        "opt_out_steps": {
          "ko": [
            "ChatGPT 에서 계정 메뉴 › 설정을 열어요",
            "데이터 제어(Data controls)를 눌러요",
            "'모든 사용자를 위한 모델 개선(Improve the model for everyone)'을 꺼요"
          ],
          "en": [
            "In ChatGPT, open the account menu › Settings",
            "Tap Data controls",
            "Turn off 'Improve the model for everyone'"
          ]
        },
        "retention": {
          "ko": "임시 채팅은 안전을 위해 최대 30일 보관해요.",
          "en": "Temporary chats are kept up to 30 days for safety."
        },
        "zdr": {
          "ko": "개인 요금제에는 해당 없어요.",
          "en": "Not available on personal plans."
        },
        "sources": [
          "https://help.openai.com/en/articles/5722486-how-your-data-is-used-to-improve-model-performance",
          "https://help.openai.com/en/articles/7730893-data-controls-in-chatgpt"
        ]
      },
      "balance": null,
      "dashboard_url": "https://chatgpt.com/settings/usage",
      "privacy_request": null,
      "kind": "chat"
    },
