    {
      "id": "openrouter",
      "section": "api_key",
      "status": "ready",
      "name": {
        "ko": "OpenRouter",
        "en": "OpenRouter"
      },
      "tagline": {
        "ko": "키 하나로 수백 개 AI · 무료 모델도 있어요",
        "en": "One key, hundreds of AIs · Free models included"
      },
      "connection": "chat_completions",
      "base_url": "https://openrouter.ai/api/v1",
      "auth": {
        "type": "bearer",
        "oauth": {
          "type": "openrouter_pkce",
          "authorize": "https://openrouter.ai/auth",
          "exchange": "https://openrouter.ai/api/v1/auth/keys",
          "callback": "loopback",
          "key_label": "Gurumi",
          "note": {
            "ko": "로그인 후 키가 자동으로 넘어와요 — 붙여넣기 필요 없음",
            "en": "The key comes back automatically after sign-in"
          }
        }
      },
      "key_page": "https://openrouter.ai/settings/keys",
      "billing_page": "https://openrouter.ai/settings/credits",
      "key_info_api": "https://openrouter.ai/api/v1/key",
      "key_prefixes": [
