          "en": [
            "Open privacy settings on openrouter.ai (settings › privacy)",
            "Turn off routing to services that may train (separate for paid and free models)"
          ]
        },
        "retention": {
          "ko": "OpenRouter 는 저장하지 않아요. 답하는 회사마다 보관 기간이 달라요.",
          "en": "OpenRouter keeps nothing; each answering company has its own retention."
        },
        "zdr": {
          "ko": "누구나 개인정보 설정에서 켤 수 있어요.",
          "en": "Anyone can turn it on in privacy settings."
        },
